  "source": "def simulate_actions(actions):
    committed_ids = set()
    max_committed_id = 0
    in_transaction = False
    txn_puts = []
    txn_deletes = []

    for action in actions:
        op = action["op"]
        if op == "put":
            id_val = action["id"]
            if in_transaction:
                txn_puts.append(id_val)
            else:
                committed_ids.add(id_val)
                if id_val > max_committed_id:
                    max_committed_id = id_val
        elif op == "delete":
            id_val = action["id"]
            if in_transaction:
                txn_deletes.append(id_val)
            else:
                if id_val in committed_ids:
                    committed_ids.discard(id_val)
        elif op == "begin":
            in_transaction = True
            txn_puts = []
            txn_deletes = []
        elif op == "commit":
            for p_id in txn_puts:
                committed_ids.add(p_id)
                if p_id > max_committed_id:
                    max_committed_id = p_id
            for d_id in txn_deletes:
                if d_id in committed_ids:
                    committed_ids.discard(d_id)
            in_transaction = False
            txn_puts = []
            txn_deletes = []
        elif op == "rollback":
            in_transaction = False
            txn_puts = []
            txn_deletes = []
    return max_committed_id

